def solution(prices):
    best_start, best_len = 0, 0
    start, length = 0, 0
    for i, p in enumerate(prices):
        if p == 0:
            length = 0
            continue
        if length > 0 and p > prices[i - 1]:
            length += 1
        else:
            start, length = i + 1, 1
        if length > best_len:
            best_start, best_len = start, length
    return [best_start, best_len]
